using System;
using System.Web.UI;
using System.Web.UI.WebControls;
using Sunplus.Accounting.Core.Web;
using Sunplus.Accounting.Core.Web;
using DNAide.Web;
using Sunplus.Bingo.Core;


public partial class Report_WinLoss_default : ReportMasterPageBase
{
    protected DateTime _fromDate;
    protected DateTime _toDate;
    protected string _option;
    protected string _currentUrl;
    protected string _downlineUrl;
    protected int _uplineId;
    protected string _reportTitle;


    protected void Page_Load(object sender, EventArgs e)
    {        
        
        if (!Page.IsPostBack)
        {
            var page = this.Page as WinLossReporPageBase;

            if (page != null)
            {
                _fromDate = page.FromDate;
                _toDate = page.ToDate;
                _option = page.Option;
                _currentUrl = page.CurrentUrl;
                _downlineUrl = page.DownlineUrl;
                _uplineId = page.UplineId;
                _reportTitle = page.ReportTitle;               
            }
        } 
        GenHeader();                
    }

    public override ImageButton ExportButton
    {
        get { return btnExport; }
    }

    protected void btnExport_Click(object sender, ImageClickEventArgs e)
    {
        if (Request.QueryString["option"] == null)
            return;
         var page = this.Page as WinLossReporPageBase;
         if (page != null)
         {
             page.ExportExcelFile();
         }
    }

    private void GenHeader() 
    {
        var tplHeader = WebUtils.LoadTemplateBySystem("Winlost/WinLossDetailChecksList.htm", true);

        TemplateHandler.Assign(ref tplHeader, "{reportTitle}", _reportTitle);
        if (!BingoSettings.NumberGame.Enabled)
            TemplateHandler.RemoveBlock(ref tplHeader, "no-numbergame");
        if (!BingoSettings.BingoGame.Enabled)
            TemplateHandler.RemoveBlock(ref tplHeader, "no-bingo");

        ltrHeader.Text = tplHeader;
    }
}
